        self.assertEqual(parse_cache_control("max-age=x, max-age=20"), {"max-age": 20})
        self.assertEqual(parse_cache_control("no-cache, NO-CACHE"), {"no-cache": True})
        self.assertEqual(parse_cache_control("ext=a, ext=b"), {"ext": "a"})

